//region helper functions for table rendering
onSortColumnClick = async function(evnt) {
  var err, key, results;
  key = evnt.target.getAttribute("data-key");
  log(`onSortColumnClick: ${key}`);
  if (sortColumn === key) {
    sortAscending = !sortAscending; // Toggle direction
// switch sort column
  } else {
    sortColumn = key;
    sortAscending = false; // New column: start descending
  }
  results = (await screener.getResults(sortColumn, sortAscending));
  try {
    render(results);
  } catch (error) {
    err = error;
    console.error(err);
  }
};

//###########################################################
formatPercent = function(value) {
  var sign;
  sign = value >= 0 ? "+" : "";
  return `${sign}${value.toFixed(1)}%`;
};

addSymbolSpan = function(td, result) {
  var clsPostfix, cotSignal, direction, symbol, trend, wsma52Aligned;
  symbol = result.symbol;
  direction = result.direction;
  trend = result.trend;
  cotSignal = result.cotSignal;
  wsma52Aligned = result.wsma52Aligned;
  if (symbol == null) {
    throw new Error("Result had no symbol defined!");
  }
  td.appendChild(getSpan("symbol", symbol));
  if (direction == null) {
    return;
  }
  clsPostfix = direction.toLowerCase();
  td.classList.add(`sym-${clsPostfix}`);
  //# TODO add isSMA53 as additional condition 
  if ((trend === 0 || (trend > 0)) && cotSignal === direction && wsma52Aligned) {
    td.classList.add("confirmed");
  }
};

addScoreSpan = function(td, score) {
  var color, text;
  if (typeof score === "string") {
    score = parseFloat(score);
  }
  ({color, text} = getTrendForScore(score));
  score = Math.round(score);
  if (score > 30) {
    score = 30;
  }
  if (score < -30) {
    score = -30;
  }
  if (score > 0) {
    score = "+" + score;
  }
  td.classList.add("score");
  td.style.backgroundColor = color;
  td.appendChild(getSpan("", `${text} ${score}`));
};

addCOTSpan = function(td, cotBase, cotQuote) {
  if (typeof cotBase === "string") {
    cotBase = parseInt(cotBase);
  }
  if (typeof cotQuote === "string") {
    cotQuote = parseInt(cotQuote);
  }
  if (cotBase >= 80) {
    td.appendChild(getSpan("strong-cot", `${Math.round(cotBase)}`));
  } else if (cotBase <= 20) {
    td.appendChild(getSpan("weak-cot", `${Math.round(cotBase)}`));
  } else {
    td.appendChild(getSpan("neutral-cot", `${Math.round(cotBase)}`));
  }
  td.appendChild(getSpan("", " / "));
  if (cotQuote >= 80) {
    td.appendChild(getSpan("strong-cot", `${Math.round(cotQuote)}`));
  } else if (cotQuote <= 20) {
    td.appendChild(getSpan("weak-cot", `${Math.round(cotQuote)}`));
  } else {
    td.appendChild(getSpan("neutral-cot", `${Math.round(cotQuote)}`));
  }
};

addWinrateSpan = function(td, winrate) {
  var cls;
  cls = "winrate";
  if (winrate >= 70) {
    cls += " positive";
  }
  // if winrate <= 30 then cls += " negative"
  td.appendChild(getSpan(cls, winrate.toFixed(1)));
};

formatDate = function(value) {
  var date, day, dayStr, month, monthStr, year;
  date = new Date(value);
  day = date.getDate();
  month = date.getMonth() + 1;
  year = date.getFullYear();
  dayStr = day < 10 ? `0${day}` : `${day}`;
  monthStr = month < 10 ? `0${month}` : `${month}`;
  return `${dayStr}.${monthStr}.${year}`;
};

//###########################################################
getSpan = function(cls, txt) {
  var span;
  span = document.createElement("SPAN");
  span.className = cls;
  span.textContent = txt;
  return span;
};

getColoredPercentSpan = function(num, dec = 0) {
  var cls, span;
  if (num > 0) {
    cls = "up";
  }
  if (num < 0) {
    cls = "down";
  }
  span = document.createElement("SPAN");
  span.className = cls;
  span.textContent = num.toFixed(dec);
  return span;
};

getColoredNumSpan = function(num, dec = 0) {
  var cls, span;
  if (num > 0) {
    cls = "positive";
  }
  if (num < 0) {
    cls = "negative";
  }
  span = document.createElement("SPAN");
  span.className = cls;
  span.textContent = num.toFixed(dec);
  return span;
};

